from pathlib import Path
import json, hashlib, statistics, datetime, os
root = Path('/home/holo/line')
base = Path('/tmp/engine-kick-gate-20261106')
prefix = base.name
out = root / 'docs/research'
results = {}
for name in ['screen', 'larger', 'cold', 'confirm']:
    path = base / name / 'result.json'
    if path.exists():
        result = json.loads(path.read_text())
        results[name] = result
        (out / f'{prefix}-{name}.json').write_text(path.read_text())
qualified = len(results) == 4 and all(r['complete'] for r in results.values())
qualified = qualified and results['confirm']['performanceQualified']
for name, result in results.items():
    if result['complete'] and name in ['larger', 'cold']:
        qualified = qualified and result['decision']['intervalPct'][1] <= {'larger': 2, 'cold': 5}[name]
    for cell in result.get('resources', []):
        a, b = [arm['resources'] for arm in cell['arms']]
        qualified = qualified and b['wasmLinearMemoryBytes'] <= a['wasmLinearMemoryBytes']
        qualified = qualified and b['processMaxRssBytes'] <= a['processMaxRssBytes'] * 1.15
ns = statistics.median(s['nsPerFrame'] for s in results['confirm']['samples'] if s['arm'] == 1) if 'confirm' in results and results['confirm']['complete'] else None
decision = {'recordedAt': datetime.datetime.now(datetime.timezone.utc).isoformat(), 'adopted': qualified,
            'confirmedCandidateMedianNsPerChargedFrame': ns, 'absoluteTargetMet': bool(qualified and ns < 7000),
            'correctness': '451 JS tests, 31 Rust tests, 65 saved/live physics cases, 63 compiler cells, 33 judge tracks, types and reach pass. Complete checkpoints61/62 equal. Shadow proves every proposed exclusion on both workloads.',
            'design': 'One conservative predicate in the detector. Original emitted angles, thresholds and arithmetic preserved; no retained data or runtime policy change.',
            'controls': 'Unchanged v3 tool and pinned runtime. Native null control from engine-node-types-20261106 remains the experiment calibration.'}
(base / 'decision.json').write_text(json.dumps(decision, indent=2) + '\n')
files = {}
for path in sorted(base.iterdir()):
    if not path.is_file() or path.suffix not in ['.ts', '.mts', '.py', '.json', '.patch', '.log']:
        continue
    data = path.read_bytes()
    files[path.name] = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data),
                       'data': json.loads(data) if path.suffix == '.json' else data.decode()}
for path in sorted((base / 'shadow').glob('*.json')):
    data = path.read_bytes()
    files[str(path.relative_to(base))] = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data), 'data': json.loads(data)}
artifacts = {}
for arm, directory in [('reference', Path('/tmp/engine-nursery-20261106/reference')), ('candidate', base / 'candidate'), ('shadow', base / 'shadow')]:
    for cell in [61, 62]:
        path = directory / f'checkpoint-{cell}.v8'
        data = path.read_bytes()
        rel = Path(arm) / path.name
        dest = root / 'generated' / prefix / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        if not dest.exists():
            os.link(path, dest)
        artifacts[str(rel)] = {'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}
(out / f'{prefix}-diagnostics.json').write_text(json.dumps({'decision': decision, 'files': files, 'localArtifacts': artifacts}, indent=2) + '\n')
print(json.dumps(decision, indent=2))
for name, result in results.items():
    print(name, result.get('decision'), [statistics.median(s['nsPerFrame'] for s in result['samples'] if s['arm'] == a) for a in [0, 1]])

