index f58b1c49..7064f609 100644
--- a/scripts/lib/detector.ts
+++ b/scripts/lib/detector.ts
@@ -375,8 +375,8 @@ function scanFrames(state: DetectorState, frames: RawFrame[], until: number): De
     if (i > 0) {
       const v0 = frames[i - 1].velocity;
       const v1 = fr.velocity;
-      const a = signedAngleDeg(v0, v1);
-      if (Math.abs(a) >= P.thetaDeg) {
+      const a = kickAngle(v0, v1, P.thetaDeg);
+      if (a !== undefined) {
         events.push({ frame: fr.frame, type: "kick", angleDeg: a });
       }
     }
@@ -488,14 +488,19 @@ function finishSummary(s: SummaryState, N: number, specDuration: number): Summar
 }

 /**
- * Signed angle from v0 to v1 in degrees, in [-180, 180].
- * Returns 0 if either vector is zero (no defined direction).
+ * Signed kick angle, or undefined when the turn is below the threshold.
+ * Zero vectors retain the detector's convention of a zero-degree turn.
  */
-function signedAngleDeg(v0: Vec2, v1: Vec2): number {
-  if ((v0.x === 0 && v0.y === 0) || (v1.x === 0 && v1.y === 0)) return 0;
+function kickAngle(v0: Vec2, v1: Vec2, threshold: number): number | undefined {
+  if ((v0.x === 0 && v0.y === 0) || (v1.x === 0 && v1.y === 0)) return threshold <= 0 ? 0 : undefined;
   const dot = v0.x * v1.x + v0.y * v1.y;
   const cross = v0.x * v1.y - v0.y * v1.x;
-  return Math.atan2(cross, dot) * (180 / Math.PI);
+  // This positive 1:4 cone is narrower than 15 degrees. Scaling by four is
+  // exact unless it overflows, in which case the strict comparison cannot pass.
+  // Cases outside this cone still use the original angle calculation.
+  if (threshold >= 15 && dot > 4 * Math.abs(cross)) return undefined;
+  const angle = Math.atan2(cross, dot) * (180 / Math.PI);
+  return Math.abs(angle) >= threshold ? angle : undefined;
 }

