import {expect, it} from 'vitest';
import {detect, type RawFrame, type Vec2} from '../scripts/lib/detector.ts';
import {makeRng} from '../scripts/lib/rng.ts';

/** The original contract, including zero vectors and binary64 operation order. */
function angle(a: Vec2, b: Vec2): number {
  if ((a.x === 0 && a.y === 0) || (b.x === 0 && b.y === 0)) return 0;
  return Math.atan2(a.x * b.y - a.y * b.x, a.x * b.x + a.y * b.y) * (180 / Math.PI);
}

function compare(velocities: Vec2[], thresholds: number[]): void {
  const frames: RawFrame[] = velocities.map((velocity, frame) => ({frame, velocity,
    position: {x: 0, y: 0}, sledContacts: [], contactLineIds: [], sledBroken: false, riderEjected: false}));
  for (const thetaDeg of thresholds) {
    const expected = velocities.slice(1).flatMap((v, i) => {
      const angleDeg = angle(velocities[i], v);
      return Math.abs(angleDeg) >= thetaDeg ? [{frame: i + 1, type: 'kick', angleDeg}] : [];
    });
    const actual = detect({duration: frames.length - 1, frames}, {thetaDeg, vStall: -Infinity})
      .events.filter(e => e.type === 'kick');
    expect(actual).toEqual(expected);
  }
}

it('preserves exact kick angles at the exclusion cone and requested thresholds', () => {
  const velocities: Vec2[] = [];
  for (const scale of [Number.MIN_VALUE, 2 ** -500, 1, 2 ** 500, Number.MAX_VALUE]) {
    for (const y of [.25 - Number.EPSILON, .25, .25 + Number.EPSILON, -.25]) {
      velocities.push({x: scale, y: 0}, {x: scale, y: y * scale});
    }
    for (const degrees of [0, 14, 15, 20, 90, 180]) {
      const radians = degrees * Math.PI / 180;
      velocities.push({x: scale, y: 0}, {x: Math.cos(radians) * scale, y: Math.sin(radians) * scale});
    }
  }
  const exactAngles = velocities.slice(1).map((v, i) => Math.abs(angle(velocities[i], v))).filter(Number.isFinite);
  compare(velocities, [-Infinity, -1, -0, Number.MIN_VALUE, 14, 15 - Number.EPSILON * 8,
    15, 15 + Number.EPSILON * 8, 20, 180, Infinity, NaN, ...new Set(exactAngles)]);
});

it('preserves kick detection for zero, nonfinite and generated extreme velocities', () => {
  const values = [0, -0, Number.MIN_VALUE, -Number.MIN_VALUE, 1, -1, Number.MAX_VALUE,
    -Number.MAX_VALUE, Infinity, -Infinity, NaN];
  const velocities = values.flatMap(x => values.map(y => ({x, y})));
  const rng = makeRng(9871);
  const value = () => (rng() - .5) * 2 ** (Math.floor(rng() * 2098) - 1074);
  for (let i = 0; i < 1000; i++) velocities.push({x: value(), y: value()});
  compare(velocities, [-Infinity, -1, 0, Number.MIN_VALUE, 1, 14.5, 15, 20, 90, 180, Infinity, NaN]);
});

